package com.mypoupar.simuladord2d;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.*;import android.webkit.*;
public class MainActivity extends Activity{
 WebView web;public void onCreate(Bundle b){super.onCreate(b);web=new WebView(this);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setGeolocationEnabled(true);web.setWebViewClient(new WebViewClient());web.setWebChromeClient(new WebChromeClient(){public void onGeolocationPermissionsShowPrompt(String o,GeolocationPermissions.Callback c){c.invoke(o,true,false);}});web.addJavascriptInterface(new Bridge(),"Android");setContentView(web);if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION},10);web.loadUrl("file:///android_asset/index.html");}
 public class Bridge{@JavascriptInterface public void street(double lat,double lng){Intent i=new Intent(Intent.ACTION_VIEW,Uri.parse("google.streetview:cbll="+lat+","+lng));i.setPackage("com.google.android.apps.maps");try{startActivity(i);}catch(Exception e){startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.google.com/maps/@?api=1&map_action=pano&viewpoint="+lat+","+lng)));}}}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
}
